using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Restore old property name for existing documents.
            entity.HasDiscriminator().HasValue("Blog");
            entity.Property<string>("$type").ToJsonProperty("Discriminator");

            // Breaking change 2: EF Core 9 uses only the key for the id property
            // instead of "Discriminator|Key". Restore old format for existing documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id).ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB provider no longer supports HasIndex.
            // Indexes are managed by Cosmos DB indexing policy, not EF Core.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}

